using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Threading;

public static class LatencyTest {
 public static void Continuous(){string[] config=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection.ini"));uint inputId=0,outputId=0;foreach(var p in MidiInput.Devices())if(p.Value==config[0])inputId=p.Key;foreach(var p in FaderReader.Devices())if(p.Value==config[1])outputId=p.Key;using(var connection=new FaderConnection(inputId,outputId,int.Parse(config[2]))){Thread.Sleep(12000);var values=new int?[96];var dates=new DateTime[96];var intervals=new List<double>();DateTime prior=DateTime.MinValue;double maxAge=0;var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<6000){connection.Copy(values,dates);if(dates[0]!=DateTime.MinValue&&dates[0]!=prior){if(prior!=DateTime.MinValue)intervals.Add((dates[0]-prior).TotalMilliseconds);prior=dates[0];maxAge=Math.Max(maxAge,(DateTime.UtcNow-prior).TotalMilliseconds);}if(connection.Error!=null)throw new Exception(connection.Error);Thread.Sleep(5);}intervals.Sort();if(intervals.Count<30)throw new Exception("Not enough continuous fader replies");using(var w=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"performance-report.txt"))){var meters=new int?[96];var meterDates=new DateTime[96];int? inp,outp;connection.CopyMeters(meters,meterDates,out inp,out outp);for(int m=0;m<96;m++)if(!meters[m].HasValue||(DateTime.UtcNow-meterDates[m]).TotalSeconds>1)throw new Exception("Missing live meter "+(m+1));if(!inp.HasValue||!outp.HasValue||connection.MeterFrames<150)throw new Exception("Meter subscription renewal or position reads failed");w.WriteLine("PASS: all 96 meters fresh after 12 seconds; frames: "+connection.MeterFrames);w.WriteLine("Meter positions: input "+MeterProtocol.PointLabel(inp)+", output "+MeterProtocol.PointLabel(outp));w.WriteLine("Read-only hardware test: six seconds after twelve-second startup warmup");w.WriteLine("Completed bank scans: "+connection.CompletedScans);w.WriteLine("Channel 1 refresh median: "+intervals[intervals.Count/2].ToString("F1")+" ms");w.WriteLine("Channel 1 refresh p95: "+intervals[(int)(intervals.Count*.95)].ToString("F1")+" ms");w.WriteLine("Last complete bank read: "+connection.LastBankReadMs.ToString("F1")+" ms");w.WriteLine("Maximum age at snapshot consumption: "+maxAge.ToString("F1")+" ms");w.WriteLine("This measures refresh cadence and reply delivery, not physical movement-to-screen latency.");}if(intervals[(int)(intervals.Count*.95)]>150)throw new Exception("Fader refresh exceeded 150 ms at p95");}}
 public static void Run(){string[] config=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection.ini"));uint inputId=0,outputId=0;foreach(var p in MidiInput.Devices())if(p.Value==config[0])inputId=p.Key;foreach(var p in FaderReader.Devices())if(p.Value==config[1])outputId=p.Key;int dev=int.Parse(config[2]);using(var report=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"latency-report.txt"))){report.AutoFlush=true;using(var input=new MidiInput(inputId))using(var output=new FaderReader(outputId)){var timings=new List<double>();for(int cycle=0;cycle<12;cycle++){bool[] seen=new bool[24];int got=0;var watch=Stopwatch.StartNew();for(int c=0;c<24;c++)output.Read(c,dev);while(got<24&&watch.ElapsedMilliseconds<2000){input.Pump();byte[] packet;while(input.Packets.TryDequeue(out packet)){int c,v;if(FaderProtocol.TryRead(packet,out c,out v)&&c<24&&!seen[c]){seen[c]=true;got++;}}Thread.Sleep(1);}report.WriteLine("24-fader read batch: "+watch.Elapsed.TotalMilliseconds.ToString("F1")+" ms; replies "+got+"/24");timings.Add(watch.Elapsed.TotalMilliseconds);}report.WriteLine("Passive change capture begins (12 seconds, no outgoing requests)");var passive=Stopwatch.StartNew();int changes=0;while(passive.ElapsedMilliseconds<12000){input.Pump();byte[] packet;while(input.Packets.TryDequeue(out packet)){int c,v;if(FaderProtocol.TryRead(packet,out c,out v)){report.WriteLine("Unsolicited fader event: channel "+(c+1)+" raw "+v+" at "+passive.ElapsedMilliseconds+" ms");changes++;}}Thread.Sleep(1);}timings.Sort();report.WriteLine("Median complete-bank read: "+timings[timings.Count/2].ToString("F1")+" ms; passive fader events: "+changes);}}}
}


